// The bundled ADS theme artifacts export their token CSS as a string. The
// package ships types under dist/types only, so the ESM paths are declared here.
declare module '@atlaskit/tokens/dist/esm/artifacts/themes/atlassian-light' {
  const css: string;
  export default css;
}
declare module '@atlaskit/tokens/dist/esm/artifacts/themes/atlassian-dark' {
  const css: string;
  export default css;
}
